using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "UnpredictableEffect", menuName = "Data/Battle/Effects/Enemy/Unpredictable Effect")]
public class UnpredictableEffect : Effect
{
	[Header("Reactive Specifics")]
	[SerializeField]
	private RerollAction rerollAction;

	[NonSerialized]
	private bool alreadyActivated;

	[NonSerialized]
	private int startingAmount;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedDescription = GetLocalizedDescription();
		if (amount == EffectsValues.NO_VALUE || amount == -1)
		{
			string[] list = localizedDescription.Split('\n');
			return GetEffectDescriptionWithAmountReplacedWithX(list.First(), GetNumberToReplaceWithX(), null);
		}
		return Smart.Format(localizedDescription, startingAmount, amount);
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		alreadyActivated = false;
		startingAmount = effectAmount;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		if (instance.PreviouslyGameState == instance.StartPlayerTurnState || instance.StartPlayerTurnState.StartTurnActivations.Count > 0 || instance.PreviouslyGameState == instance.EndPlayerTurnState || instance.EndPlayerTurnState.EndTurnActivations.Count > 0 || ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.EnemyTurn || alreadyActivated || !effectOwner.GetComponent<UnitsDiceActivation>().BasicDiceSpawned)
		{
			return effectAmount;
		}
		UnitEffects component = effectOwner.GetComponent<UnitEffects>();
		int num = effectAmount - 1;
		if (num == 0)
		{
			alreadyActivated = true;
			instance.ActionsQueueState.EnqueueAfterAction(ActivateUnpredictable(effectOwner, component));
			if (instance.CurrentState != instance.PrecisionActionState)
			{
				instance.SetActionsQueueState();
			}
		}
		component.IsEffectActiveAndDecreaseEffect(this, 1, activateFeedback: true, removeOnZero: false);
		if (num == 1)
		{
			component.IsEffectActiveGetEffectInstance(this).PlayBlinkingFeedback();
		}
		return num;
	}

	private IEnumerator ActivateUnpredictable(GameObject effectOwner, UnitEffects unitEffects)
	{
		yield return InvokeAlternatives.WaitForFrames(3);
		if (!effectOwner.GetComponent<CorruptionStats>().IsDefeated())
		{
			PlayEffectActivationSFX();
			List<DiceInstance> diceInstancesToRoll = effectOwner.GetComponent<CorruptedAnimalActivation>().GetDiceInstancesToRoll();
			rerollAction.ExternalCast(diceInstancesToRoll, RollDiceActionType.REROLL, null);
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 4f);
			unitEffects.RemoveEffect(this, activateFeedback: false);
			yield return new WaitForSeconds(0.1f);
			alreadyActivated = false;
		}
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		if (!effectOwner.GetComponent<CorruptionStats>().IsDefeated())
		{
			effectOwner.GetComponent<UnitEffects>().AddEffect(this, startingAmount, effectFeedback: true, callEffectsCallbacks: false);
		}
	}
}
